BEGIN;
SET LOCAL lock_timeout='5s';
SELECT set_config('request.jwt.claim.sub','b8cbf27e-2391-4fb5-b061-f1488e8c3135',true);
-- Transaction-only budget isolation: restored by ROLLBACK; no production quota is increased.
UPDATE public.audit_logs SET created_at=created_at-interval '2 days' WHERE action IN ('skill_research.claimed','subtitle.claimed','document.claimed') AND created_at>=date_trunc('day',now());
DO $test$
DECLARE owner uuid:=auth.uid(); manager uuid; other_manager uuid; job uuid; job2 uuid; research uuid; reused uuid; token uuid; source public.document_jobs; ids uuid[]:='{}'; report jsonb; denied boolean;
BEGIN
 SELECT id INTO manager FROM public.agents WHERE code='COO' AND is_active LIMIT 1;
 IF manager IS NULL THEN RAISE EXCEPTION 'Fixture manager missing';END IF;
 SELECT id INTO other_manager FROM public.agents WHERE code='CTO' AND is_active LIMIT 1;
 job:=public.create_document_job(manager,'Synthetic document verification failure','pdf_extract_v1',gen_random_uuid());ids:=array_append(ids,job);
 denied:=false;BEGIN PERFORM public.queue_document_job(job);EXCEPTION WHEN SQLSTATE '22023' THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Missing input accepted';END IF;
 INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('company-documents',owner::text||'/'||job::text||'/input','{"size":100}');
 PERFORM public.queue_document_job(job);SELECT research_job_id INTO research FROM public.document_jobs WHERE id=job;
 IF research IS NULL OR (SELECT state FROM public.document_jobs WHERE id=job)<>'waiting_skill' THEN RAISE EXCEPTION 'Skill research not automatic';END IF;
 token:=gen_random_uuid();UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '10 minutes',input=input||'{"runner_id":"900001/1"}' WHERE id=research;
 PERFORM public.finish_skill_research(research,token,'900001/1','{"candidates":[],"summary":"No applicable fixture"}');
 IF (SELECT state FROM public.document_jobs WHERE id=job)<>'failed' THEN RAISE EXCEPTION 'Unverified capability enabled';END IF;
 job:=public.create_document_job(manager,'Synthetic validated document task','docx_create_v1',gen_random_uuid());ids:=array_append(ids,job);
 INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('company-documents',owner::text||'/'||job::text||'/input','{"size":100}');
 PERFORM public.queue_document_job(job);SELECT research_job_id INTO research FROM public.document_jobs WHERE id=job;
 token:=gen_random_uuid();UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '10 minutes',input=input||'{"runner_id":"900001/2"}' WHERE id=research;
 report:=jsonb_build_object('candidates',jsonb_build_array(jsonb_build_object('repository','Estrella-lc/ai-company-os','commit_sha',repeat('a',40),'skill_path','skills/document-processing/SKILL.md','name','synthetic-document-adapter','description','Synthetic transaction fixture, no actual library run','document','Synthetic adapter description','metadata',jsonb_build_object('adapter','company_documents_v1','requirements_sha256',repeat('c',64)),'verification',jsonb_build_object('passed',true,'scope','document_processing_v1','passed_count',10,'isolation',jsonb_build_object('network_disabled',true,'unprivileged',true,'root_read_only',true,'secrets_absent',true),'profiles',jsonb_build_array('pdf_extract_v1','docx_extract_v1','docx_create_v1')))));
 IF NOT public.finish_skill_research(research,token,'900001/2',report) THEN RAISE EXCEPTION 'Research callback failed';END IF;
 IF (SELECT state FROM public.document_jobs WHERE id=job)<>'queued' OR (SELECT skill_id FROM public.document_jobs WHERE id=job) IS NULL THEN RAISE EXCEPTION 'Document not resumed';END IF;
 SELECT * INTO source FROM public.claim_document_job('900001/3');
 IF source.id<>job OR source.attempt_count<>1 THEN RAISE EXCEPTION 'Wrong document lease';END IF;
 IF (SELECT id FROM public.claim_document_job('900001/3')) IS DISTINCT FROM job OR EXISTS(SELECT 1 FROM public.claim_document_job('900001/4')) THEN RAISE EXCEPTION 'Concurrent duplicate document claim';END IF;
 IF public.finish_document_job(job,gen_random_uuid(),'900001/3','{}',true) THEN RAISE EXCEPTION 'Foreign lease accepted';END IF;
 report:=jsonb_build_object('passed',true,'scope','docx_create_v1','input_sha256',repeat('a',64),'output_sha256',repeat('b',64),'output_bytes',100);
 denied:=false;BEGIN PERFORM public.finish_document_job(job,source.lease_token,'900001/3',report);EXCEPTION WHEN SQLSTATE '22023' THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Missing artifact accepted';END IF;
 INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('company-documents',source.output_path,'{"size":100}');
 IF NOT public.finish_document_job(job,source.lease_token,'900001/3',report) OR NOT public.finish_document_job(job,source.lease_token,'900001/3',report) THEN RAISE EXCEPTION 'Completion/idempotence failed';END IF;
 IF (SELECT review FROM public.document_jobs WHERE id=job) IS NOT NULL THEN RAISE EXCEPTION 'Automatic CEO acceptance';END IF;
 IF public.finish_document_job(job,gen_random_uuid(),'900001/3',report) THEN RAISE EXCEPTION 'Terminal stale token accepted';END IF;
 PERFORM public.review_document_job(job,'accept','Synthetic transaction-only acceptance');
 IF (SELECT review->>'state' FROM public.document_jobs WHERE id=job)<>'accepted' THEN RAISE EXCEPTION 'CEO review not saved';END IF;
 reused:=private.enqueue_skill_research(owner,manager,'员工能力缺口：docx create','docx create',NULL,gen_random_uuid());
 IF (SELECT input->>'capability' FROM public.tasks WHERE id=reused)<>'documents' OR (SELECT result->>'reused' FROM public.tasks WHERE id=reused) IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'DOCX classification or skill reuse failed';END IF;
 job2:=public.create_document_job(other_manager,'Synthetic cross-manager reusable document capability','pdf_extract_v1',gen_random_uuid());ids:=array_append(ids,job2);
 INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('company-documents',owner::text||'/'||job2::text||'/input','{"size":100}');
 PERFORM public.queue_document_job(job2);
 IF (SELECT state FROM public.document_jobs WHERE id=job2)<>'queued' OR (SELECT research_job_id FROM public.document_jobs WHERE id=job2) IS NOT NULL THEN RAISE EXCEPTION 'Shared capability not reused';END IF;
 SELECT * INTO source FROM public.claim_document_job('900001/5');
 UPDATE public.document_jobs SET lease_expires_at=now()-interval '1 second' WHERE id=source.id;
 SELECT * INTO source FROM public.claim_document_job('900001/6');
 IF source.id<>job2 OR source.attempt_count<>2 THEN RAISE EXCEPTION 'Lease recovery failed';END IF;
 UPDATE public.document_jobs SET lease_expires_at=now()-interval '1 second' WHERE id=source.id;
 PERFORM public.claim_document_job('900001/7');
 IF (SELECT state FROM public.document_jobs WHERE id=job2)<>'failed' THEN RAISE EXCEPTION 'Recovery exceeded limit';END IF;
 IF (SELECT count(*) FROM public.audit_logs WHERE action='document.claimed' AND created_at>=date_trunc('day',now()))<>3 THEN RAISE EXCEPTION 'Shared budget not recorded';END IF;
 IF EXISTS(SELECT 1 FROM public.claim_skill_research('900001/8')) THEN RAISE EXCEPTION 'Research bypassed shared document budget';END IF;
 IF has_function_privilege('authenticated','public.claim_document_job(text)','EXECUTE') OR has_function_privilege('authenticated','public.finish_document_job(uuid,uuid,text,jsonb,boolean)','EXECUTE') OR has_table_privilege('authenticated','public.document_jobs','UPDATE') THEN RAISE EXCEPTION 'Browser privilege escalation';END IF;
END $test$;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.document_jobs) OR EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='company-documents') THEN RAISE EXCEPTION 'Document RLS leak';END IF;END $$;
RESET ROLE;
ROLLBACK;
SELECT 'PASS: document research, failed verification, shared reuse, leases, concurrent claims, output gate, recovery cap, shared budget, CEO acceptance and RLS; all rolled back' AS checks;
